\set ON_ERROR_STOP on
begin;

-- ══════ СОГАЗ: общие правила ДМС + приложение «Стоматологическое обслуживание» ══════
-- ВНИМАНИЕ: PDF отсканирован, текстовый слой искажён («диетапираванных» = дистопированных,
-- «У2» = ½). Извлекаем только однозначно читаемые пункты; спорное не берём.
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/sogaz_pravila_dms.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/sogaz_pravila_dms.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, v.pn, v.sc, v.sp, v.vd, v.ct, v.la, v.cl,
       case when v.pn is null then 'insurer' else 'program' end, false
from d cross join (values
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-приёмы','приём консультация стоматолог терапевт хирург пародонтолог ортопед детский','covered','включая стоматологию ортодонтическую и имплантологическую как специальность приёма',null,'п. 2.1'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','документы-справки','оформление выдача медицинской документации','covered',null,null,'п. 2.2'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','диагностика','радиовизиография дентальные снимки ортопантомограмма компьютерная томография','covered',null,null,'п. 2.3'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','анестезия местная инфильтрационная аппликационная проводниковая','covered',null,null,'п. 2.4'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-хирургия','общая анестезия','covered',null,null,'п. 2.5'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','лечение кариеса светоотверждаемые материалы лечебная прокладка некариозные поражения','covered',null,null,'п. 2.6'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','лечение пульпита пломбирование каналов гуттаперча термофилы','conditional','постоянная пломба — при сохранении не менее 1/2 коронковой части зуба',null,'п. 2.7'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','лечение хронического периодонтита в стадии обострения распломбировка каналов','conditional','постоянная пломба — при сохранении не менее 1/2 коронковой части зуба',null,'п. 2.8'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','замена пломбы','covered',null,null,'п. 2.9'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','лечение пришеечного кариеса','conditional','при сохранении половины или более коронки зуба',null,'п. 2.10'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','восстановление коронки разрушенной более 50% без штифтов','covered',null,null,'п. 2.11'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','восстановление коронки анкерный штифт','covered',null,null,'п. 2.12'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-хирургия','удаление зуб простое сложное','covered',null,null,'п. 2.13'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-хирургия','удаление ретинированных дистопированных зубов','covered',null,null,'п. 2.13'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-хирургия','доброкачественные новообразования челюстно-лицевой области разрезы вскрытие абсцессов капюшон','covered',null,null,'п. 2.13'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','пародонтология','снятие зубных отложений глубокое фторирование покрытие лаком при гиперестезии','covered',null,null,'п. 2.14'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','пародонтология','консервативное лечение пародонта аппликации инстилляции повязка','conditional','лечение заболеваний тканей пародонта I–II степени, купирование острых состояний',null,'п. 2.14'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-профилактика','герметизация фиссур отбеливание реставрация зубных рядов косметическое восстановление','conditional','услуги в профилактических и косметических целях — по условиям договора',null,'п. 2.14'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-терапия','лечение слизистой оболочки полости рта языка','covered',null,null,'п. 2.15'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-хирургия','лечение заболеваний слюнных желёз','covered',null,null,'п. 2.16'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','имплантация','имплантация зубопротезирование съёмные фиксированные протезы костные трансплантаты','conditional','входит в объём только если прямо предусмотрено договором страхования',null,'п. 2.17'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','ортодонтия','ортодонтические виды лечения','conditional','входит в объём только если прямо предусмотрено договором страхования',null,'п. 2.18'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','стоматология-физио','стоматологические физиотерапевтические процедуры','covered',null,null,'п. 2.19'),
('Стоматологическое обслуживание (приложение к Правилам ДМС СОГАЗ)','лекарства','лекарственные средства изделия медназначения при процедурах','covered',null,null,'п. 2.20'),
(null,'общие-исключения','алкогольное наркотическое токсическое опьянение','excluded',null,null,'п. 3.9.1'),
(null,'общие-исключения','умышленные противоправные действия','excluded',null,null,'п. 3.9.2'),
(null,'общие-исключения','покушение на самоубийство','excluded','кроме случаев доведения противоправными действиями третьих лиц',null,'п. 3.9.3'),
(null,'общие-исключения','умышленное причинение себе телесных повреждений','excluded',null,null,'п. 3.9.4'),
(null,'общие-исключения','особо опасные инфекционные болезни','excluded',null,null,'п. 3.9.5'),
(null,'общие-условия','перечень заболеваний вне покрытия определяется программой договора','conditional','перечень заболеваний, обращение по которым не является застрахованным, указывается в программе к договору',null,'п. 3.4 – 3.5')
) as v(pn, sc, sp, vd, ct, la, cl);

-- ══════ РОСГОССТРАХ: правила ДМС №152 ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/rgs_dms_152.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/rgs_dms_152.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой случай обращение за медицинской помощью по программе','conditional','страховой случай — обращение застрахованного в медицинскую организацию из числа предусмотренных договором за услугами, входящими в программу','Раздел 3 «СТРАХОВОЙ РИСК И СТРАХОВЫЕ СЛУЧАИ»'),
('общие-условия','франшиза доля собственного участия','conditional','договором может быть предусмотрена франшиза — часть расходов оплачивает застрахованный','Раздел 5 «ФРАНШИЗА»'),
('общие-условия','страховая сумма лимит выплат','conditional','объём обязательств ограничен страховой суммой по договору','Раздел 4 «ПОРЯДОК ОПРЕДЕЛЕНИЯ СТРАХОВОЙ СУММЫ»'),
('общие-условия','порядок обращения и оплаты услуг','conditional','порядок получения услуг и оплаты определяется договором и программой страхования','Раздел 11 «ПОРЯДОК ОСУЩЕСТВЛЕНИЯ СТРАХОВЫХ ВЫПЛАТ»')
) as v(sc, sp, vd, ct, cl);

-- ══════ ЭНЕРГОГАРАНТ: правила ДМС №125 ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/energogarant_dms_125.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/energogarant_dms_125.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховые риски и страховые случаи','conditional','страховым случаем признаётся обращение за медицинской помощью в объёме программы страхования','Раздел 4 «СТРАХОВЫЕ РИСКИ И СТРАХОВЫЕ СЛУЧАИ»'),
('общие-исключения','исключения из страхового покрытия','excluded','перечень исключений установлен разделом 5 Правил и программой к договору','Раздел 5 «ИСКЛЮЧЕНИЯ ИЗ СТРАХОВОГО ПОКРЫТИЯ»'),
('общие-условия','страховая сумма франшиза','conditional','страховая сумма и франшиза определяются договором','Раздел 6 «СТРАХОВАЯ СУММА. ФРАНШИЗА»')
) as v(sc, sp, vd, ct, cl);

-- ══════ РЕНЕССАНС: правила ДМС (ред. 7.0) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/renins_dms.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/renins_dms.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой риск обращение в медицинскую организацию','conditional','страховой риск — расходы на медицинскую помощь при обращении застрахованного в медицинскую или фармацевтическую организацию','Раздел 4 «Страховые риски. Страховой случай»'),
('общие-исключения','исключения из страхового покрытия','excluded','перечень исключений установлен разделом 4 Правил и программой к договору','Раздел 4 «исключения из страхового покрытия»'),
('общие-условия','страховая сумма тариф франшиза','conditional','страховая сумма, тариф и франшиза определяются договором','Раздел 5 «Страховая сумма. Страховой тариф. Страховая премия. Франшиза»'),
('общие-условия','порядок обращения за медицинской помощью','conditional','порядок обращения и определения выплаты установлен разделом 7 Правил','Раздел 7 «Порядок обращения за медицинской помощью»')
) as v(sc, sp, vd, ct, cl);

-- ══════ ЗЕТТА: правила ДМС (приказ №75 от 11.09.2023) ══════
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/zetta_dms.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/zetta_dms.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','правила дмс зетта действуют с 15.09.2023','conditional','правила утверждены приказом АО «Зетта Страхование» №75 от 11.09.2023, действуют с 15.09.2023','Приказ №75 от 11 сентября 2023')
) as v(sc, sp, vd, ct, cl);

select left(ic.name,22) || ' | ' || left(pd.title,44) || ' | правил: ' ||
  (select count(*) from coverage_rule cr where cr.document_id = pd.id)
from program_document pd join insurance_company ic on ic.id = pd.insurance_company_id
where pd.superseded_by_id is null order by ic.name;
commit;
